import React, { useEffect, useState } from "react";
import Navbar from "./Navbar";
import CardsSeries from "./CardsSeries";
import axios from "axios";
import { NavLink } from "react-router-dom";

const MaListeSérie = () => {
  const [listData, setListData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const seriesId = window.localStorage.series
          ? window.localStorage.series.split(",")
          : [];

        const donnéesSéries = await Promise.all(
          seriesId.map(async (id) => {
            const response = await axios.get(
              `https://api.themoviedb.org/3/tv/${id}?api_key=ed82f4c18f2964e75117c2dc65e2161d&language=fr-FR`
            );
            return response.data;
          })
        );

        setListData(donnéesSéries);
        setLoading(false);
      } catch (erreur) {
        setError(erreur.message);
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div>Chargement...</div>;
  }

  if (error) {
    return <div>Erreur : {error}</div>;
  }

  return (
    <div className="fav-page">
      <Navbar />
      <h2>Ma liste de séries</h2>
      <ul className="catalogue">
        {listData.length > 0 ? (
          listData.map((série) => (
            <NavLink to={`/SeriesPopulaires/${série.id}`} key={série.id}>
              <CardsSeries série={série} />
            </NavLink>
          ))
        ) : (
          <h2>Aucune série dans votre liste</h2>
        )}
      </ul>
    </div>
  );
};

export default MaListeSérie;
